changeSet.sql:
ALTER TABLE nexus.frecency NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.frecency
     WHERE chunk_id !~ '^[0-9a-f]{64}$';
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'nexus-lgdel.l1: deleted % legacy-width nexus.frecency row(s) (chunk_id not canonical 64-hex)', v_deleted_count;
END $$;

ALTER TABLE nexus.frecency FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.relevance_log NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.relevance_log
     WHERE chunk_id !~ '^[0-9a-f]{64}$';
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'nexus-lgdel.l1: deleted % legacy-width nexus.relevance_log row(s) (chunk_id not canonical 64-hex)', v_deleted_count;
END $$;

ALTER TABLE nexus.relevance_log FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.frecency
    ADD CONSTRAINT frecency_chunk_id_canonical_check CHECK (chunk_id ~ '^[0-9a-f]{64}$');

ALTER TABLE nexus.relevance_log
    ADD CONSTRAINT relevance_log_chunk_id_canonical_check CHECK (chunk_id ~ '^[0-9a-f]{64}$');

rollback.sql:
CREATE TABLE nexus.chash_alias (
    tenant_id  TEXT  NOT NULL DEFAULT '',
    old_ref    TEXT  NOT NULL,
    old_bytes  BYTEA NOT NULL,
    new_chash  BYTEA NOT NULL,
    source     TEXT  NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chash_alias_pk PRIMARY KEY (tenant_id, old_ref),
    CONSTRAINT chash_alias_new_octet_check CHECK (octet_length(new_chash) = 32)
);
CREATE INDEX idx_chash_alias_old_bytes ON nexus.chash_alias (tenant_id, old_bytes);
CREATE INDEX idx_chash_alias_new ON nexus.chash_alias (tenant_id, new_chash);
ALTER TABLE nexus.chash_alias ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.chash_alias FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.chash_alias
    USING (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));
